ADMIN_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VoiceRecap Admin</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#e8eef5;background:#0b1120}body{margin:0}header{padding:18px 24px;border-bottom:1px solid #22304a;display:flex;justify-content:space-between;align-items:center;background:#101a2d}h1{font-size:20px;margin:0}main{max-width:1400px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.card{background:#111c30;border:1px solid #243653;border-radius:14px;padding:16px;box-shadow:0 8px 30px #0003}.metric{font-size:30px;font-weight:700;margin-top:8px}.muted{color:#91a2bc}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.tabs button,.primary{background:#3568e8;color:white;border:0;border-radius:9px;padding:10px 14px;cursor:pointer}.tabs button.secondary{background:#1b2a45}.panel{display:none}.panel.active{display:block}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:10px}input,select,textarea{background:#0b1425;color:#e8eef5;border:1px solid #304565;border-radius:8px;padding:10px;min-width:160px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #253653;padding:9px;text-align:left;vertical-align:top}th{color:#a9bcda}button.small{padding:6px 9px;font-size:12px;border:0;border-radius:6px;background:#294b86;color:white;cursor:pointer}.danger{background:#8e3142!important}.ok{color:#70e0a2}.warn{color:#ffd27a}.error{color:#ff8598}.toast{position:fixed;right:20px;bottom:20px;background:#1d2e4e;padding:12px 16px;border-radius:9px;display:none}.formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.formgrid label{display:flex;flex-direction:column;gap:5px;color:#9db0cd;font-size:12px}.wide{grid-column:1/-1}.badge{padding:3px 7px;border-radius:99px;background:#203b69}
</style></head><body>
<header><h1>VoiceRecap Control Center</h1><div class="row"><span id="who" class="muted">Signed out</span><button class="small" onclick="logout()">Logout</button></div></header>
<main>
<section id="login" class="card"><h2>Admin sign in</h2><p class="muted">Use the same VoiceRecap account marked as administrator.</p><div class="row"><input id="email" type="email" placeholder="admin email"><input id="password" type="password" placeholder="password"><button class="primary" onclick="login()">Sign in</button></div><div id="loginError" class="error"></div></section>
<section id="app" style="display:none">
<div class="grid" id="metrics"></div>
<div class="tabs"><button onclick="tab('users')">Users</button><button class="secondary" onclick="tab('plans')">Plans & pricing</button><button class="secondary" onclick="tab('payments')">Payments</button><button class="secondary" onclick="tab('credentials')">Provider credentials</button><button class="secondary" onclick="tab('aiModels')">AI provider models</button><button class="secondary" onclick="tab('settings')">Runtime settings</button><button class="secondary" onclick="tab('jobs')">Jobs</button><button class="secondary" onclick="tab('audit')">Audit log</button></div>
<section id="users" class="panel active card"><h2>User management</h2><div class="row"><input id="userQuery" placeholder="Search email/name"><button class="primary" onclick="loadUsers()">Search</button></div><div id="usersTable"></div></section>
<section id="plans" class="panel card"><h2>Plan and credit pricing</h2><p class="muted">Create plans with credits, per-video credit cost, MMK price, and USDT price. Values are intentionally admin-controlled.</p><div class="formgrid"><label>Name<input id="pName" placeholder="Creator 100"></label><label>Description<input id="pDesc"></label><label>Included credits<input id="pCredits" type="number" min="0" value="100"></label><label>Credits per video<input id="pVideo" type="number" min="0" value="10"></label><label>Extra credits per minute<input id="pMinute" type="number" min="0" value="0"></label><label>TTS credits / 100 chars<input id="pTts" type="number" min="0" value="1"></label><label>Voice clone credits<input id="pClone" type="number" min="0" value="0"></label><label>Price MMK<input id="pMmk" type="number" min="0" value="0"></label><label>Price USDT<input id="pUsdt" value="0"></label><label>Validity days<input id="pDays" type="number" min="0" value="30"></label><label>Max video seconds<input id="pMax" type="number" min="1" value="1800"></label><label>Sort order<input id="pSort" type="number" value="10"></label></div><br><button class="primary" onclick="createPlan()">Create plan</button><div id="plansTable"></div></section>
<section id="payments" class="panel card"><h2>Payment review</h2><p class="muted">Approve only after checking the submitted MMK or USDT transaction externally. Approval grants the plan credits exactly once.</p><div id="paymentsTable"></div></section>
<section id="credentials" class="panel card"><h2>Provider credentials</h2><p class="muted">API keys are entered and rotated here. They are encrypted by the Worker before saving to D1; this page only shows the last 4 characters. Built-in OpenRouter and OpenCode Zen are supported, and Custom is for HTTPS OpenAI-compatible providers.</p><div class="formgrid"><label>Credential name<input id="cName" placeholder="Zen key 1"></label><label>Provider<select id="cProvider" onchange="syncCredentialForm()"><option value="openrouter_stt">OpenRouter built-in</option><option value="opencode_zen">OpenCode Zen built-in</option><option value="custom">Custom provider</option></select></label><label>API key<input id="cApiKey" type="password" autocomplete="new-password" placeholder="Enter key; never displayed again"></label><label>Auth<select id="cAuth"><option value="bearer">Bearer</option><option value="x_api_key">X-API-Key/custom header</option><option value="none">No authentication</option></select></label><label>Auth header<input id="cHeader" value="Authorization"></label><label>API format<select id="cFormat"><option value="openai_chat">OpenAI chat completions</option><option value="openai_audio_transcription">OpenAI audio transcription</option><option value="openai_responses">OpenAI responses</option><option value="anthropic_messages">Anthropic messages</option><option value="custom_json">Custom JSON</option></select></label><label class="wide">Custom base URL (required only for Custom)<input id="cBaseUrl" placeholder="https://provider.example/v1"></label><label class="wide">Model catalog URL (optional)<input id="cModelsUrl" placeholder="https://provider.example/v1/models"></label></div><br><div class="row"><button class="primary" onclick="createCredential()">Save encrypted credential</button><span id="credentialStatus" class="muted"></span></div><div id="credentialsTable"></div></section><section id="settings" class="panel card"><h2>Runtime settings</h2><p class="muted">These settings are stored in D1 and take effect without a Worker code change. Failed, DNS, provider-capacity, and rate-limit attempts do not count toward the Free daily limit. Set the limit to 0 for unlimited completed jobs.</p><div class="formgrid"><label>Free daily completed jobs<input id="freeDailyLimit" type="number" min="0" max="10000000" value="3"></label></div><br><button class="primary" onclick="saveSettings()">Save settings</button><span id="settingsStatus" class="muted"></span><div id="settingsTable"></div></section><section id="aiModels" class="panel card"><h2>AI provider models</h2><p class="muted">Select an encrypted credential, fetch that provider’s live catalog, then add models in priority order. Priority 0 is first. A request is sent once; model fallback happens only inside that one request.</p><div class="formgrid"><label>Provider<select id="aProvider" onchange="syncAiForm()"><option value="openrouter_stt">OpenRouter — Whisper STT</option><option value="opencode_zen">OpenCode Zen — translation</option><option value="custom">Custom provider</option></select></label><label>Capability<select id="aCapability"><option value="stt">Speech-to-text</option><option value="translation">Translation</option></select></label><label>Encrypted credential<select id="aCredential"><option value="">Load credentials first</option></select></label><label>Priority (0 first)<input id="aPriority" type="number" min="0" value="0"></label><label>RPM limit<input id="aRpm" type="number" min="1" value="10"></label><label>Daily limit<input id="aDaily" type="number" min="1" value="100"></label><label>Concurrency<input id="aConc" type="number" min="1" value="1"></label><label class="wide">Live model<select id="aModel"><option value="">Fetch catalog first</option></select></label></div><br><div class="row"><button class="primary" onclick="fetchAiCatalog()">Fetch live models</button><button class="small" onclick="addAiModel()">Add selected model</button><span id="aiCatalogStatus" class="muted"></span></div><div id="aiModelsTable"></div></section>
<section id="jobs" class="panel card"><h2>Processing jobs</h2><div id="jobsTable"></div></section>
<section id="audit" class="panel card"><h2>Immutable audit trail</h2><div id="auditTable"></div></section>
</section></main><div id="toast" class="toast"></div>
<script>
const state={token:localStorage.getItem('vr_admin_access')};const $=id=>document.getElementById(id);function api(path,opt={}){opt.headers={...(opt.headers||{}),Authorization:`Bearer ${state.token}`,'Content-Type':'application/json'};return fetch(path,opt).then(async r=>{const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.detail||`HTTP ${r.status}`);return b})}function toast(x){$('toast').textContent=x;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function table(rows,cols,actions=''){if(!rows?.length)return '<p class="muted">No records.</p>';return `<table><thead><tr>${cols.map(c=>`<th>${esc(c[1])}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(typeof c[0]==='function'?c[0](r):r[c[0]])}</td>`).join('')}<td>${actions?actions(r):''}</td></tr>`).join('')}</tbody></table>`}function tab(id){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');({users:loadUsers,plans:loadPlans,payments:loadPayments,credentials:loadCredentials,aiModels:loadAiModels,settings:loadSettings,jobs:loadJobs,audit:loadAudit}[id]||(()=>{}))()}async function login(){try{const b=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('email').value,password:$('password').value})}).then(async r=>{const x=await r.json();if(!r.ok)throw Error(x.detail||'Sign in failed');return x});state.token=b.access_token;localStorage.setItem('vr_admin_access',state.token);await init()}catch(e){$('loginError').textContent=e.message}}function logout(){localStorage.removeItem('vr_admin_access');location.reload()}async function init(){try{const me=await api('/api/v1/auth/me');if(!me.is_admin)throw Error('This account is not an administrator');$('login').style.display='none';$('app').style.display='block';$('who').textContent=me.email;await Promise.all([loadSummary(),loadUsers(),loadPlans()])}catch(e){localStorage.removeItem('vr_admin_access');$('loginError').textContent=e.message}}async function loadSummary(){const x=await api('/api/v1/admin/summary');$('metrics').innerHTML=Object.entries(x).map(([k,v])=>`<div class="card"><div class="muted">${esc(k.replaceAll('_',' '))}</div><div class="metric">${esc(v)}</div></div>`).join('')}async function loadUsers(){const x=await api('/api/v1/admin/users?q='+encodeURIComponent($('userQuery').value));$('usersTable').innerHTML=table(x,[['email','Email'],['display_name','Name'],['credits','Credits'],['is_active','Active'],['is_banned','Banned'],['created_at','Created']],r=>`<button class="small" onclick="grant('${r.id}')">Grant</button> <button class="small danger" onclick="ban('${r.id}',${!r.is_banned})">${r.is_banned?'Unban':'Ban'}</button>`)}async function grant(id){const n=prompt('Credits to grant');if(!n)return;const description=prompt('Reason','Admin grant');if(!description)return;await api('/api/v1/admin/credits/grant',{method:'POST',body:JSON.stringify({user_id:id,credits:Number(n),description,idempotency_key:'admin-'+id+'-'+Date.now()})});toast('Credits granted');await loadUsers()}async function ban(id,b){await api('/api/v1/admin/users/'+id,{method:'PATCH',body:JSON.stringify({is_banned:b})});toast('User updated');await loadUsers()}async function loadPlans(){const x=await api('/api/v1/admin/plans');$('plansTable').innerHTML='<br>'+table(x,[['name','Name'],['included_credits','Credits'],['video_credit_cost','Video cost'],['price_mmk','MMK'],['price_usdt','USDT'],['active','Active'],['validity_days','Days']],r=>`<button class="small" onclick="togglePlan('${r.id}',${!r.active})">${r.active?'Disable':'Enable'}</button>`)}async function createPlan(){const b={name:$('pName').value,description:$('pDesc').value||null,included_credits:Number($('pCredits').value),video_credit_cost:Number($('pVideo').value),video_credit_cost_per_minute:Number($('pMinute').value),tts_credit_per_100_chars:Number($('pTts').value),voice_clone_credit_cost:Number($('pClone').value),price_mmk:Number($('pMmk').value),price_usdt:$('pUsdt').value,validity_days:Number($('pDays').value),max_video_duration_seconds:Number($('pMax').value),sort_order:Number($('pSort').value),active:true};await api('/api/v1/admin/plans',{method:'POST',body:JSON.stringify(b)});toast('Plan created');await loadPlans()}async function togglePlan(id,active){const x=await api('/api/v1/admin/plans');const p=x.find(a=>a.id===id);p.active=active;await api('/api/v1/admin/plans/'+id,{method:'PATCH',body:JSON.stringify(p)});await loadPlans()}async function loadPayments(){const x=await api('/api/v1/admin/payments');$('paymentsTable').innerHTML=table(x,[['email','User'],['plan_name','Plan'],['currency','Currency'],['amount','Amount'],['status','Status'],['transaction_reference','Reference'],['created_at','Created']],r=>r.status==='submitted'?`<button class="small" onclick="approve('${r.id}')">Approve</button>`:'')}async function approve(id){if(!confirm('Approve and grant credits?'))return;await api('/api/v1/admin/payments/'+id+'/approve',{method:'POST'});toast('Payment approved');await loadPayments();await loadSummary()}async function loadSettings(){try{const x=await api('/api/v1/admin/settings');const s=x.find(r=>r.key==='free_daily_job_limit');if(s){$('freeDailyLimit').value=s.value}$('settingsTable').innerHTML='<br>'+table(x,[['key','Key'],['value','Value'],['description','Description'],['updated_at','Updated']]);$('settingsStatus').textContent='Loaded'}catch(e){$('settingsStatus').textContent='Load failed: '+e.message}}async function saveSettings(){const value=Number($('freeDailyLimit').value);if(!Number.isInteger(value)||value<0){toast('Enter 0 or a positive whole number');return}try{await api('/api/v1/admin/settings/free_daily_job_limit',{method:'PATCH',body:JSON.stringify({key:'free_daily_job_limit',value})});toast('Runtime settings saved');await loadSettings()}catch(e){toast('Save failed: '+e.message)}}let credentialRows=[];async function loadCredentials(){try{credentialRows=await api('/api/v1/admin/provider-credentials');$('credentialsTable').innerHTML=table(credentialRows,[['name','Name'],['provider_type','Provider'],['credential_last4','Key last 4'],['api_format','Format'],['base_url','Base URL'],['enabled','Enabled'],['last_test_status','Last test']],r=>`<button class="small danger" onclick="disableCredential('${r.id}')">Disable</button>`);syncAiForm()}catch(e){$('credentialStatus').textContent='Load failed: '+e.message}}function syncCredentialForm(){const custom=$('cProvider').value==='custom';$('cBaseUrl').required=custom;$('credentialStatus').textContent=custom?'Custom providers require HTTPS base URL.':'Built-in provider selected'}async function createCredential(){const b={name:$('cName').value.trim(),provider_type:$('cProvider').value,api_key:$('cApiKey').value,base_url:$('cBaseUrl').value.trim()||null,models_url:$('cModelsUrl').value.trim()||null,api_format:$('cFormat').value,auth_type:$('cAuth').value,auth_header:$('cHeader').value.trim()||'Authorization',enabled:true};if(!b.name||!b.api_key){toast('Credential name and API key are required');return}try{await api('/api/v1/admin/provider-credentials',{method:'POST',body:JSON.stringify(b)});$('cApiKey').value='';toast('Encrypted credential saved');await loadCredentials()}catch(e){$('credentialStatus').textContent='Save failed: '+e.message}}async function disableCredential(id){if(!confirm('Disable this credential and all models attached to it?'))return;await api('/api/v1/admin/provider-credentials/'+id,{method:'DELETE'});toast('Credential disabled');await loadCredentials();await loadAiModels()}function syncAiForm(){const p=$('aProvider').value,c=$('aCapability');if(p==='openrouter_stt')c.value='stt';if(p==='opencode_zen')c.value='translation';const usable=credentialRows.filter(x=>x.enabled&&(x.provider_type===p||(p==='custom'&&x.provider_type==='custom')));$('aCredential').innerHTML=usable.length?usable.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} ••••${esc(x.credential_last4||'')}</option>`).join(''):'<option value="">Create credential first</option>';$('aModel').innerHTML='<option value="">Fetch catalog first</option>';$('aiCatalogStatus').textContent=''}async function loadAiModels(){const x=await api('/api/v1/admin/ai-models');$('aiModelsTable').innerHTML='<br>'+table(x,[['provider','Provider'],['capability','Use'],['model_id','Model'],['credential_id','Credential'],['credential_configured','Key OK'],['priority','Priority'],['active_requests','Active'],['daily_used','Daily'],['cooldown_until','Cooldown']],r=>`<button class="small" onclick="testAiModel('${r.id}')">Test</button> <button class="small" onclick="toggleAiModel('${r.id}',${!r.enabled})">${r.enabled?'Disable':'Enable'}</button> <button class="small danger" onclick="removeAiModel('${r.id}')">Delete</button>`);if(!credentialRows.length)await loadCredentials();else syncAiForm()}async function fetchAiCatalog(){const p=$('aProvider').value,c=$('aCapability').value,id=$('aCredential').value;if(!id){toast('Create/select an encrypted credential first');return}$('aiCatalogStatus').textContent='Fetching live catalog...';try{const x=await api('/api/v1/admin/ai-models/catalog?provider='+encodeURIComponent(p)+'&capability='+encodeURIComponent(c)+'&credential_id='+encodeURIComponent(id));window.aiCatalog=x.models||[];$('aModel').innerHTML=window.aiCatalog.length?window.aiCatalog.map((m,i)=>`<option value="${i}">${esc(m.display_name||m.model_id)} — ${esc(m.model_id)}${m.is_free?' — free':''}</option>`).join(''):'<option value="">No models returned</option>';$('aiCatalogStatus').textContent=(x.models||[]).length+' live models fetched'}catch(e){$('aiCatalogStatus').textContent='Fetch failed: '+e.message}}async function addAiModel(){const i=Number($('aModel').value),m=(window.aiCatalog||[])[i],credential_id=$('aCredential').value;if(!m||!credential_id){toast('Fetch/select a model and encrypted credential first');return}const b={provider:$('aProvider').value,capability:$('aCapability').value,model_id:m.model_id,display_name:m.display_name,secret_name:'ADMIN_VAULT',credential_id,priority:Number($('aPriority').value),enabled:true,rpm_limit:Number($('aRpm').value),daily_limit:Number($('aDaily').value),concurrency_limit:Number($('aConc').value),catalog:m};await api('/api/v1/admin/ai-models',{method:'POST',body:JSON.stringify(b)});toast('AI model added');await loadAiModels()}async function testAiModel(id){try{const x=await api('/api/v1/admin/ai-models/'+id+'/test',{method:'POST'});toast(x.ok?'Provider/model test passed':(x.error||'Provider/model test failed'));await loadAiModels()}catch(e){toast('Test failed: '+e.message)}}async function toggleAiModel(id,enabled){const x=await api('/api/v1/admin/ai-models');const r=x.find(a=>a.id===id);if(!r)return;r.enabled=enabled;await api('/api/v1/admin/ai-models/'+id,{method:'PATCH',body:JSON.stringify(r)});toast(enabled?'Model enabled':'Model disabled');await loadAiModels()}async function removeAiModel(id){if(!confirm('Delete this provider model?'))return;await api('/api/v1/admin/ai-models/'+id,{method:'DELETE'});toast('Model deleted');await loadAiModels()}async function loadJobs(){const x=await api('/api/v1/admin/jobs');$('jobsTable').innerHTML=table(x,[['email','User'],['status','Status'],['target_language','Language'],['credits_reserved','Reserved'],['provider_model','Model'],['error_message','Error'],['created_at','Created']])}async function loadAudit(){const x=await api('/api/v1/admin/audit');$('auditTable').innerHTML=table(x,[['created_at','Time'],['action','Action'],['actor_user_id','Actor'],['target_type','Target'],['target_id','Target ID'],['metadata_json','Metadata']])}if(state.token)init();
</script></body></html>'''
